// 「做完」的四种动作。this 是视图；ctx = { id, origin, scr, commit }
// 做法：把便签复制一份放到视图最上层（fx 层）去演动画，原便签马上由 commit() 从数据里标记完成、重画，周围便签补位
var CNP_FX = {
  // 静物：便签本上的整张扯走；墙上的从下往上揭起、掉下去
  still: async function(ctx) {
    var pad = ctx.scr.querySelector(cnpSel("p", ctx.id)), el = ctx.scr.querySelector(cnpSel("w", ctx.id));
    var P = "perspective(700px) ";
    if (ctx.origin === "pad" && pad) {
      var g = this.cnpGhost(pad); g.style.rotate = "-1.2deg"; g.style.transformOrigin = "50% 0";
      var curl = g.createEl("i", { cls: "sl-curl" });
      if (el) el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 220, fill: "forwards" });
      ctx.commit();
      CNP_SND.peel();
      cnpAnim(curl, [{ opacity: 0 }, { opacity: 1 }], { duration: 260 });
      await cnpAnim(g, [{ transform: P + "rotateX(0deg)" }, { transform: P + "rotateX(34deg) translateY(-3px)" }], { duration: 280, easing: "cubic-bezier(.3,.6,.4,1)" });
      CNP_SND.tear();
      await cnpAnim(g, [{ transform: P + "rotateX(34deg) translateY(-3px)", opacity: 1 }, { transform: P + "translate(150px, -80px) rotateX(60deg) rotateZ(16deg)", opacity: 0 }], { duration: 560, easing: "cubic-bezier(.55,0,.8,.4)" });
      return;
    }
    if (!el) { ctx.commit(); return; }
    var g2 = this.cnpGhost(el); g2.style.transformOrigin = "50% 0";
    var sheet = g2.querySelector(".sl-sheet") || g2;
    var curl2 = sheet.createEl("i", { cls: "sl-curl" });
    el.style.visibility = "hidden";
    CNP_SND.peel();
    cnpAnim(curl2, [{ opacity: 0 }, { opacity: 1 }], { duration: 300 });
    await cnpAnim(g2, [{ transform: P + "rotateX(0deg)" }, { transform: P + "rotateX(40deg)" }], { duration: 320, easing: "cubic-bezier(.3,.6,.4,1)" });
    CNP_SND.tear();
    ctx.commit();
    await cnpAnim(g2, [{ transform: P + "rotateX(40deg)", opacity: 1 }, { transform: P + "translate(16px, 340px) rotateX(74deg) rotateZ(-20deg)", opacity: 0 }], { duration: 660, easing: "cubic-bezier(.5,0,.9,.5)" });
  },
  // 手帐：先盖完成章，再沿纸胶带下沿撕开，下半截掉落，胶带和残纸停一会儿
  journal: async function(ctx) {
    var li = ctx.scr.querySelector(cnpSel("l", ctx.id)), el = ctx.scr.querySelector(cnpSel("w", ctx.id));
    if (li) li.addClass("ticking");
    if (!el) { await cnpSleep(li ? 820 : 0); ctx.commit(); return; }
    var paper = el.querySelector(".jo-paper");
    paper.insertAdjacentHTML("beforeend", cnpStampJo());
    var stamp = paper.lastElementChild;
    CNP_SND.thud();
    await cnpAnim(stamp, [{ transform: "scale(1.8)", opacity: 0 }, { transform: "scale(.94)", opacity: 1, offset: 0.72 }, { transform: "scale(1)", opacity: 1 }], { duration: 260, easing: "cubic-bezier(.5,0,.7,1)" });
    el.animate([{ translate: "0 0" }, { translate: "0 2px" }, { translate: "0 0" }], { duration: 150 });
    await cnpSleep(420);
    var w = el.offsetWidth, h = el.offsetHeight, y0 = Math.round(h * 0.27), steps = 14, pts = [];
    for (var i = 0; i <= steps; i++) pts.push([Math.round(w * i / steps), y0 + Math.round((cnpHash(ctx.id + ":" + i) - 0.5) * 10)]);
    var P = function(a) { return a.map(function(p) { return p[0] + "px " + p[1] + "px"; }).join(","); };
    var last = pts[pts.length - 1][1];
    var topClip = "polygon(-40px -50px," + (w + 40) + "px -50px," + (w + 40) + "px " + last + "px," + P(pts.slice().reverse()) + ",-40px " + pts[0][1] + "px)";
    var botClip = "polygon(-40px " + pts[0][1] + "px," + P(pts) + "," + (w + 40) + "px " + last + "px," + (w + 40) + "px " + (h + 60) + "px,-40px " + (h + 60) + "px)";
    var rim = '<svg class="jo-rim" width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + " " + h + '" aria-hidden="true"><polyline points="' + pts.map(function(p) { return p.join(","); }).join(" ") + '"/></svg>';
    var gTop = this.cnpGhost(el), gBot = this.cnpGhost(el);
    gTop.style.clipPath = topClip; gBot.style.clipPath = botClip;
    gTop.insertAdjacentHTML("beforeend", rim); gBot.insertAdjacentHTML("beforeend", rim);
    el.style.visibility = "hidden";
    gBot.style.transformOrigin = "0 27%";
    CNP_SND.tear();
    var fall = cnpAnim(gBot, [{ transform: "translate(0,0) rotate(0deg)" }, { transform: "translate(3px, 7px) rotate(6deg)", offset: 0.22 }, { transform: "translate(30px, 320px) rotate(30deg)", opacity: 0 }], { duration: 920, easing: "cubic-bezier(.45,0,.8,.6)" });
    await cnpSleep(560);
    cnpAnim(gTop, [{ opacity: 1 }, { opacity: 0 }], { duration: 520 });
    await fall;
    ctx.commit();
    await cnpSleep(140);
  },
  // 笺：印章落下盖「毕」，抬起后笺纸对折收走
  jian: async function(ctx) {
    var li = ctx.scr.querySelector(cnpSel("l", ctx.id)), el = ctx.scr.querySelector(cnpSel("w", ctx.id));
    if (!el) { if (li) li.addClass("sealing"); await cnpSleep(li ? 520 : 0); ctx.commit(); return; }
    var paper = el.querySelector(".ji-paper");
    var stone = paper.createEl("i", { cls: "ji-stone" });
    await cnpAnim(stone, [{ transform: "scale(1.7) translateY(-18px)", opacity: 0, boxShadow: "0 26px 26px rgba(0,0,0,.22)" }, { transform: "scale(1) translateY(0)", opacity: 1, boxShadow: "0 2px 3px rgba(0,0,0,.3)" }], { duration: 320, easing: "cubic-bezier(.6,0,.9,.6)" });
    CNP_SND.thud();
    paper.insertAdjacentHTML("beforeend", '<i class="ji-imp"><b>毕</b></i>');
    if (li) li.addClass("sealing");
    await cnpSleep(120);
    await cnpAnim(stone, [{ transform: "scale(1)", opacity: 1 }, { transform: "scale(1.45) translateY(-22px)", opacity: 0 }], { duration: 340, easing: "ease-out" });
    stone.remove();
    await cnpSleep(280);
    var base = this.cnpGhost(el), w = el.offsetWidth, h = el.offsetHeight;
    var root = document.createElement("div"); root.className = "ji-fold";
    Object.assign(root.style, { position: "absolute", left: base.style.left, top: base.style.top, width: w + "px", height: h + "px", perspective: "1000px" });
    base.parentNode.insertBefore(root, base); root.appendChild(base);
    Object.assign(base.style, { left: "0px", top: "0px", clipPath: "inset(50% -30px -30px -30px)" });
    var flap = root.createDiv();
    Object.assign(flap.style, { position: "absolute", left: "0", top: "0", width: w + "px", height: h / 2 + "px", transformOrigin: "50% 100%", transformStyle: "preserve-3d" });
    var front = flap.createDiv();
    Object.assign(front.style, { position: "absolute", inset: "0", overflow: "hidden", backfaceVisibility: "hidden" });
    var face = base.cloneNode(true); face.style.clipPath = "none"; front.appendChild(face);
    var color = Array.prototype.find.call(el.classList, function(x) { return x.indexOf("p-") === 0; }) || "";
    var back = flap.createDiv({ cls: "ji-back " + color });
    Object.assign(back.style, { position: "absolute", inset: "0", transform: "rotateX(180deg)", backfaceVisibility: "hidden" });
    el.style.visibility = "hidden";
    CNP_SND.fold();
    await cnpAnim(flap, [{ transform: "rotateX(0deg)" }, { transform: "rotateX(-180deg)" }], { duration: 600, easing: "cubic-bezier(.5,0,.3,1)" });
    ctx.commit();
    await cnpAnim(root, [{ transform: "translateY(0) scale(1)", opacity: 1 }, { transform: "translateY(40px) scale(.9)", opacity: 0 }], { duration: 400, easing: "ease-in" });
  },
  // 孔版：揉成纸团，抛进 DONE 筐，计数跳一下
  riso: async function(ctx) {
    var li = ctx.scr.querySelector(cnpSel("l", ctx.id)), el = ctx.scr.querySelector(cnpSel("w", ctx.id));
    if (li) li.addClass("striking");
    if (!el) { await cnpSleep(li ? 560 : 0); ctx.commit(); return; }
    var g = this.cnpGhost(el);
    g.createEl("i", { cls: "ri-wrinkle" });
    var outer = document.createElement("div");
    Object.assign(outer.style, { position: "absolute", left: "0", top: "0", width: "0", height: "0" });
    g.parentNode.insertBefore(outer, g); outer.appendChild(g);
    el.style.visibility = "hidden";
    var map = this.cnpDefs && this.cnpDefs.querySelector("feDisplacementMap");
    if (map) g.style.filter = "url(#" + this.cnpFilterId + ")";
    CNP_SND.crumple();
    if (map) cnpRamp(map, "scale", 0, 26, 440);
    cnpAnim(g.querySelector(".ri-wrinkle"), [{ opacity: 0 }, { opacity: 1 }], { duration: 440 });
    await cnpAnim(g, [{ transform: "scale(1) rotate(0deg)", borderRadius: "0" }, { transform: "scale(.4) rotate(150deg)", borderRadius: "46%" }], { duration: 460, easing: "cubic-bezier(.4,0,.6,1)" });
    ctx.commit();
    var binB = ctx.scr.querySelector("[data-bin] b"), total = binB ? binB.textContent : "";
    if (binB) binB.textContent = cnpPad2(Math.max(0, +total - 1));
    var binEl = ctx.scr.querySelector("[data-bin]"), gr = g.getBoundingClientRect(), dx = 0, dy = -200;
    if (binEl) { var br = binEl.getBoundingClientRect(); dx = br.left + br.width / 2 - (gr.left + gr.width / 2); dy = br.top + br.height / 2 - (gr.top + gr.height / 2); }
    var peak = Math.min(dy, 0) - 90;
    CNP_SND.whoosh();
    outer.animate([{ transform: "translateX(0)" }, { transform: "translateX(" + dx + "px)" }], { duration: 640, easing: "linear", fill: "forwards" });
    await cnpAnim(g, [
      { transform: "translateY(0) scale(.4) rotate(150deg)", easing: "cubic-bezier(.2,.6,.4,1)" },
      { transform: "translateY(" + peak + "px) scale(.32) rotate(330deg)", offset: 0.45, easing: "cubic-bezier(.6,0,.8,.4)" },
      { transform: "translateY(" + dy + "px) scale(.18) rotate(520deg)", opacity: 0.9 }
    ], { duration: 640, easing: "linear" });
    if (map) map.setAttribute("scale", "0");
    var binB2 = ctx.scr.querySelector("[data-bin] b");
    if (binB2) { binB2.textContent = total; binB2.animate([{ transform: "scale(1)" }, { transform: "scale(1.45)" }, { transform: "scale(1)" }], { duration: 320, easing: "ease-out" }); }
    CNP_SND.thud(0.45);
  }
};
